#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/timing/timing.h>

#define SLEEP_MS 100
#define SLEEP_US 1000

/*
 * @brief Test k_sleep(K_NO_WAIT)
 */
ZTEST(sleep_tests, test_k_sleep_0)
{
	int64_t start_time = k_uptime_get();
	k_sleep(K_NO_WAIT);
	int64_t end_time = k_uptime_get();
	zassert_true(end_time - start_time < 1, "k_sleep(K_NO_WAIT) slept too long");
}

/*
 * @brief Test k_sleep(K_MSEC(1))
 */
ZTEST(sleep_tests, test_k_sleep_1)
{
	int64_t start_time = k_uptime_get();
	k_sleep(K_MSEC(1));
	int64_t end_time = k_uptime_get();
	zassert_true(end_time - start_time >= 1, "k_sleep(K_MSEC(1)) slept too short");
	zassert_true(end_time - start_time < (1 + K_MSEC(CONFIG_KERNEL_TIMER_TICK_MS)),
				 "k_sleep(K_MSEC(1)) slept too long");
}

/*
 * @brief Test k_msleep(0)
 */
ZTEST(sleep_tests, test_k_msleep_0)
{
	int64_t start_time = k_uptime_get();
	k_msleep(0);
	int64_t end_time = k_uptime_get();
	zassert_true(end_time - start_time < 1, "k_msleep(0) slept too long");
}

/*
 * @brief Test k_msleep(SLEEP_MS)
 */
ZTEST(sleep_tests, test_k_msleep_1)
{
	int64_t start_time = k_uptime_get();
	k_msleep(SLEEP_MS);
	int64_t end_time = k_uptime_get();
	zassert_true(end_time - start_time >= SLEEP_MS, "k_msleep(SLEEP_MS) slept too short");
	zassert_true(end_time - start_time < (SLEEP_MS + K_MSEC(CONFIG_KERNEL_TIMER_TICK_MS)),
				 "k_msleep(SLEEP_MS) slept too long");
}

/*
 * @brief Test k_usleep(0)
 */
ZTEST(sleep_tests, test_k_usleep_0)
{
	int64_t start_time = k_uptime_get();
	k_usleep(0);
	int64_t end_time = k_uptime_get();
	zassert_true(end_time - start_time < 1, "k_usleep(0) slept too long");
}

/*
 * @brief Test k_usleep(SLEEP_US)
 */
ZTEST(sleep_tests, test_k_usleep_1)
{
	int64_t start_time = k_uptime_get();
	k_usleep(SLEEP_US);
	int64_t end_time = k_uptime_get();
	zassert_true(end_time - start_time >= (SLEEP_US / 1000), "k_usleep(SLEEP_US) slept too short");
	zassert_true(end_time - start_time < ((SLEEP_US / 1000) + K_MSEC(CONFIG_KERNEL_TIMER_TICK_MS)),
				 "k_usleep(SLEEP_US) slept too long");
}

/*
 * @brief Test k_busy_wait(0)
 */
ZTEST(sleep_tests, test_k_busy_wait_0)
{
	timing_t start_cycles = timing_cycles_get();
	k_busy_wait(0);
	timing_t end_cycles = timing_cycles_get();
	zassert_true(timing_cycles_to_ns(end_cycles - start_cycles) < 1000,
				 "k_busy_wait(0) waited too long");
}

/*
 * @brief Test k_busy_wait(SLEEP_US)
 */
ZTEST(sleep_tests, test_k_busy_wait_1)
{
	timing_t start_cycles = timing_cycles_get();
	k_busy_wait(SLEEP_US);
	timing_t end_cycles = timing_cycles_get();
	zassert_true(timing_cycles_to_ns(end_cycles - start_cycles) >= SLEEP_US,
				 "k_busy_wait(SLEEP_US) waited too short");
	/* Allow for some overhead, e.g., 10% */
	zassert_true(timing_cycles_to_ns(end_cycles - start_cycles) < (SLEEP_US * 1.1),
				 "k_busy_wait(SLEEP_US) waited too long");
}

/*
 * @brief Test k_wakeup_msleep(SLEEP_MS)
 */
ZTEST(sleep_tests, test_k_wakeup_msleep)
{
	int64_t start_time;
	int64_t end_time;
	int64_t delta;

	start_time = k_uptime_get();
	k_wakeup_msleep(SLEEP_MS);
	end_time = k_uptime_get();

	delta = end_time - start_time;

	/* k_wakeup_msleep() guarantees to sleep at least the requested time.
	 * It may sleep longer due to tick alignment or other factors.
	 */
	zassert_true(delta >= SLEEP_MS, "k_wakeup_msleep slept too short");
	zassert_true(delta < (SLEEP_MS + K_MSEC(CONFIG_KERNEL_TIMER_TICK_MS)),
				 "k_wakeup_msleep slept too long");
}

ZTEST_SUITE(sleep_tests, NULL, NULL, NULL, NULL, NULL);
